      "title": "District Data (Censuses 1950–1987) / Kreisdaten (Volkszählungen 1950–1987)",
      "url_or_doi": "https://doi.org/10.4232/1.2472",
      "justification": "This GESIS aggregate dataset contains district-level (Kreis) structural data across West German federal states, including North Rhine-Westphalia, from 1950 to the 1987 census. It covers population density, household sizes, housing conditions, commuters, and local economic structures in urban and rural areas during the 1980s."
    },
    {
      "title": "German General Social Survey ALLBUS 1980 (Allgemeine Bevölkerungsumfrage der Sozialwissenschaften ALLBUS 1980)",
      "url_or_doi": "https://doi.org/10.4232/1.1000",
      "justification": "A representative social survey from 1980 archived by GESIS, covering West Germany including North Rhine-Westphalia. It includes microdata on personal living conditions, local community life, social networks, and regional demographic classifications."
    },
    {
      "title": "German General Social Survey ALLBUS 1984 (Allgemeine Bevölkerungsumfrage der Sozialwissenschaften ALLBUS 1984)",
      "url_or_doi": "https://doi.org/10.4232/1.1340",
      "justification": "This 1984 GESIS cross-sectional survey dataset captures attitudes toward social inequality, local welfare state perception, living standards, and community interaction in West German states, broken down regionally to enable research on North Rhine-Westphalia."
    },
    {
      "title": "German General Social Survey (ALLBUS) - Cumulation 1980-2012",
      "url_or_doi": "https://doi.org/10.4232/1.11952",
      "justification": "A longitudinal trend dataset compiled by GESIS that combines ALLBUS survey waves from 1980 onward, allowing researchers to analyze 1980s urban and rural life, social structure, and community engagement in North Rhine-Westphalia and broader West Germany."
    }
  ]
}
